'use strict';
const clusters=['Cagliaritano e Sud-Est','Sulcis, Oristanese e Sarcidano','Nuorese e Ogliastra','Sassarese e Nord-Ovest','Gallura'];
const locations=[
['Cagliari','V.le Diaz 79',1],['Cagliari','V.le Diaz 116',1],['Cagliari','Via Cornalias (edifici 1–2–3–4)',1],['Cagliari','Via Asproni 17, 4° piano',1],['Cagliari','P.zza Amendola c/o Enel, 1°/4° piano',1],['Assemini','Via Marconi 87',1],['Muravera','Via Roma 3B',1],['Sinnai','Impianto Potabilizzazione Corongiu',1],['Settimo S. Pietro','Impianto Potabilizzazione Simbirizzi',1],['Sarroch','Impianto Potabilizzazione',1],
['Iglesias','Via Crocifisso 92',2],['Iglesias','Loc. Sa Stoia c/o Depuratore consortile',2],['Iglesias','Via Sant’Antonio',2],['San Giovanni Suergiu','Depuratore consortile',2],['Carbonia','Piazza Roma 1 c/o Municipio',2],['Nuxis','Impianto Bau Pressiu',2],['Sanluri','Loc. Nuragonnos, prol. Via Donizetti (edifici 1–2)',2],['Isili','Via G. Deledda 3',2],['Oristano','Via Toscanini 6',2],['Oristano-Silì','Impianto Potabilizzazione',2],
['Macomer','Via S. Antonio 14',3],['Nuoro','V.le Costituzione 91',3],['Nuoro','Loc. Bischollai, Via Straullu 35',3],['Lanusei','Via Venezia 9',3],['Tortolì','Via Monsignor Virgilio 74A',3],
['Sassari','Via Principessa Jolanda 81',4],['Sassari','Viale Adua 19°',4],['Sassari','Truncu Reale',4],['Alghero','Via Vitt. Emanuele 96A',4],['Thiesi','Via Don Minzoni 2',4],['Sedini','c/o Impianto Pedra Majore',4],['Ozieri','Via De Gasperi 100',4],
['Arzachena','Corso Garibaldi 13',5],['Olbia','Via Macerata 9',5],['Olbia','Via Vena Fiorita, Loc. Colcò',5],['Tempio','Via Belluno 8',5]
].map((x,i)=>({id:i+1,city:x[0],address:x[1],cluster:x[2],name:x[0]+' · '+x[1]}));
function icon(n){const paths={"calendar": "M4 5h16v15H4z M7 2v6 M17 2v6 M4 10h16 M8 14h2 M14 14h2 M8 17h2", "spark": "m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z", "file": "M6 3h8l4 4v14H6z M14 3v5h5 M9 12h6 M9 16h6", "alert": "m12 3 10 18H2z M12 9v5 M12 17v1", "case": "M3 7h18v13H3z M8 7V3h8v4 M3 12h18 M10 12v3h4v-3", "people": "M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3c0-5 14-5 14 0v3 M17 4a4 4 0 0 1 0 7 M20 14c2 1 2 4 2 7", "shield": "m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z m-4 10 3 3 5-6", "cap": "m2 8 10-5 10 5-10 5z M6 11v6c4 4 8 4 12 0v-6 M22 8v9", "leaf": "M20 3C6 1 1 9 6 17s17 2 14-14 M5 21 17 8", "home": "m2 11 10-9 10 9 M5 9v12h5v-7h4v7h5V9", "menu": "M3 6h18 M3 12h18 M3 18h18", "drop": "M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13z"};return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`}
const modules={
daily:{name:'Attività ordinarie giornaliere',short:'Ordinarie giornaliere',symbol:icon('calendar'),description:'Prestazioni di pulizia e disinfezione svolte dal lunedì al venerdì, secondo la programmazione prevista per ciascuna sede.',tabs:['Programmazione','Registro interventi','Prestazioni'],img:'daily'},
periodic:{name:'Attività ordinarie periodiche',short:'Ordinarie periodiche',symbol:icon('calendar'),description:'Prestazioni programmate con frequenza settimanale e mensile, secondo le specifiche operative del Capitolato.',tabs:['Programmazione','Registro interventi','Prestazioni'],img:'periodic'},
extra:{name:'Attività straordinarie a richiesta',short:'Straordinarie',symbol:icon('spark'),description:'Interventi di pulizia e igienizzazione non programmati, comprese disinfestazione e derattizzazione.',tabs:['Richieste','Ordini di lavoro','Registro interventi'],img:'extra'},
reports:{name:'Verbale di verifica del servizio',short:'Verbali di verifica',symbol:icon('file'),description:'Verifiche in contraddittorio con Abbanoa · Art. 18 del Capitolato',tabs:['Verbali','Contestazioni','Inadempimenti e penali']},
emergency:{name:'Gestione emergenze',short:'Gestione emergenze',symbol:icon('alert'),description:'Segnalazioni, attivazione squadra e monitoraggio dell’intero iter di gestione',tabs:['Emergenze','Squadre operative','Registro comunicazioni']},
services:{name:'Servizi Gestionali',short:'Servizi Gestionali',symbol:icon('case'),description:'Programmazione, esecuzione e controllo delle attività',tabs:['Piano di lavoro','Anagrafica sedi','Richieste e anomalie','Forniture'],bullets:['Piano di lavoro e programmazione attività','Anagrafica sedi, ambienti e superfici','Gestione richieste, anomalie ed emergenze','Forniture igieniche e sistema GSP4PFE']},
staff:{name:'Personale',short:'Personale',symbol:icon('people'),description:'Organizzazione, turni, presenze e copertura del servizio',tabs:['Operatori','Presenze e turni','Copertura','DPI e dotazioni'],bullets:['Anagrafica operatori per sede e cluster','Turni, presenze e monte ore','Copertura assenze e sostituzioni','Divise, tesserini e DPI']},
quality:{name:'Controllo Qualità',short:'Controllo Qualità',symbol:icon('shield'),description:'Verifiche di risultato, di processo e controlli in contraddittorio',tabs:['Panoramica','Controlli di risultato','Controlli di processo','Campionamento','Non conformità'],bullets:['Piano dei controlli e audit','Check-list di risultato e processo','Indicatori LQR/LQA e KPI','Non conformità e azioni correttive']},
training:{name:'Formazione',short:'Formazione',symbol:icon('cap'),description:'Competenze, addestramento operativo e scadenze formative',tabs:['Piano formativo','Anagrafica formativa','Test e attestati','Scadenziario'],bullets:['Piano formativo e corsi','Addestramento operativo e sicurezza','Test di valutazione e attestati','Report formazione e scadenze']},
sustainability:{name:'Sostenibilità',short:'Sostenibilità',symbol:icon('leaf'),description:'Monitoraggio ambientale, conformità CAM e gestione rifiuti',tabs:['Consumi','Prodotti e CAM','Macchinari FIMAP','Rifiuti NANDO','Filtri HEPA'],bullets:['Conformità ambientale e CAM','Consumi idrici, energetici e chimici','Emissioni CO₂e e macchinari','Raccolta differenziata e rifiuti']}
};
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n.toLocaleString('it-IT',{maximumFractionDigits:1,useGrouping:'always'});
let state={page:'home',cluster:'all',site:'all',period:'month',tab:0,query:''};
let saved;try{saved=JSON.parse(localStorage.getItem('abbanoa-demo')||'{}')}catch{saved={}};saved.requests??=[];saved.issues??=[];saved.attendance??={};
function persist(){try{localStorage.setItem('abbanoa-demo',JSON.stringify(saved))}catch{toast('Impossibile salvare: memoria del browser non disponibile.')}}
function scoped(){return locations.filter(s=>(state.cluster==='all'||s.cluster===+state.cluster)&&(state.site==='all'||s.id===+state.site))}
const status=(s,cls='')=>`<span class="status ${cls}">${esc(s)}</span>`;
function scopeName(){return state.site!=='all'?locations.find(s=>s.id===+state.site)?.name:state.cluster!=='all'?`Cluster ${state.cluster} · ${clusters[+state.cluster-1]}`:'Tutti i cluster · Tutte le sedi'}
function filters(home=false){return `<div class="${home?'filters':'dashboard-filters'}"><div class="filter"><label for="cluster">Cluster operativo</label><select id="cluster"><option value="all">Tutti i cluster</option>${clusters.map((c,i)=>`<option value="${i+1}" ${state.cluster==i+1?'selected':''}>Cluster ${i+1} · ${c}</option>`).join('')}</select></div><div class="filter"><label for="site">Sede</label><select id="site"><option value="all">Tutte le sedi</option>${locations.filter(s=>state.cluster==='all'||s.cluster===+state.cluster).map(s=>`<option value="${s.id}" ${state.site==s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>${home?'':`<div class="filter"><label for="period">Periodo</label><select id="period"><option value="day" ${state.period==='day'?'selected':''}>5 novembre 2026</option><option value="week" ${state.period==='week'?'selected':''}>2–8 novembre 2026</option><option value="month" ${state.period==='month'?'selected':''}>Novembre 2026</option></select></div>`}</div>`}
function nav(){if(state.page==='home'){$('#sidebar').innerHTML='';return}const groups=[['Attività',['daily','periodic','extra']],['Altre informazioni',['services','staff','quality','training','sustainability']],['Verifiche e urgenze',['reports','emergency']]];const link=(k)=>`<a href="#${k}" class="${state.page===k?'active':''}" ${state.page===k?'aria-current="page"':''}><span>${k==='home'?icon('home'):modules[k].symbol}</span>${k==='home'?'Panoramica':modules[k].short}</a>`;$('#sidebar').innerHTML=link('home')+groups.map(([title,keys])=>`<section class="nav-section"><h2>${title}</h2>${keys.map(link).join('')}</section>`).join('')+'<p class="nav-foot">36 sedi · 5 cluster operativi<br>Versione dimostrativa</p>'}

function home(){return `<section class="hero"><img class="hero-photo" src="assets/hero-v3.webp" alt="Operatori PFE impegnati nella pulizia della sede Abbanoa"><div class="hero-content"><div class="eyebrow">ABBANOA × PFE · SERVIZI INTEGRATI</div><h1>Benvenuti in<br>ABBANOA Control Hub</h1><p>Dashboard di controllo dei servizi di pulizia e disinfezione erogati da PFE presso Abbanoa.</p>${filters(true)}</div><svg class="hero-wave" viewBox="0 0 1440 100" preserveAspectRatio="none" aria-hidden="true"><path fill="#29c7eb" d="M0 10C350 0 700 100 1440 30V100H0Z"/><path fill="#078ec5" d="M0 35C420 5 700 115 1440 50V100H0Z"/><path fill="#265180" d="M0 75C400 15 750 125 1440 70V100H0Z"/></svg></section><div class="home-content"><div class="section-heading"><div><h2 id="activities">Attività</h2><p>Prestazioni previste dal Piano di lavoro del servizio</p></div><span class="scope-caption">${esc(scopeName())} · ${scoped().length} sedi</span></div><div class="activity-grid">${['daily','periodic','extra'].map((key,i)=>{const m=modules[key];return `<a class="activity-card" href="#${key}"><img src="assets/${m.img}-v2.webp" alt="${esc(m.name)}"><div class="activity-body"><div class="activity-top"><span>${i===0?'LUNEDÌ – VENERDÌ':i===1?'SETTIMANALE / MENSILE':'SU RICHIESTA'}</span><span>${m.symbol}</span></div><h3>${m.name}</h3><p>${m.description}</p><div class="activity-bottom"><span>Apri dashboard</span><span aria-hidden="true">↗</span></div></div></a>`}).join('')}</div><div class="central-actions"><a href="#reports"><span>${icon('file')} Verbale di verifica del servizio</span><span>↗</span></a><a class="emergency" href="#emergency"><span>${icon('alert')} Gestione emergenze</span><span>↗</span></a></div><div class="section-heading"><div><h2 id="information">Altre informazioni</h2><p>Dati real-time sullo svolgimento del servizio</p></div></div><div class="info-grid">${['services','staff','quality','training','sustainability'].map(key=>{let m=modules[key];return `<article class="info-card"><span class="info-icon" aria-hidden="true">${m.symbol}</span><h3>${m.name}</h3><ul>${m.bullets.map(b=>`<li>${b}</li>`).join('')}</ul><a href="#${key}" aria-label="Dettagli ${m.name}">Dettagli &nbsp; →</a></article>`}).join('')}</div><p class="home-note">Ambiente dimostrativo. Le sedi e l’articolazione del servizio provengono dal documento di progetto. Indicatori, registri e nominativi sono esempi; nessun flusso operativo è connesso.</p></div>`}
function kpis(items){const symbols=['shield','calendar','people','leaf'];return `<div class="kpis">${items.map(([label,value,note],i)=>{const name=/non conform|contestaz|penali|emergen/i.test(label)?'alert':/audit/i.test(label)?'calendar':/processo/i.test(label)?'case':/acqua|idrico/i.test(label)?'drop':/ore|tempo|puntual/i.test(label)?'calendar':/organico|addetti|squadre|assenze|sedi/i.test(label)?'people':/conform|audit|verific|esecuzione/i.test(label)?'shield':/emergen|contestaz|penali/i.test(label)?'alert':/consumo|emission/i.test(label)?'leaf':symbols[i%4];return `<div class="kpi tone-${i%4}"><div class="kpi-top"><span class="kpi-icon">${icon(name)}</span><span>${label}</span></div><strong>${value}</strong><small>${note}</small></div>`}).join('')}</div>`}

function table(headers,rows,search=false){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th${/Ore|Punt|m²|LQR|Consumo|Quantità|Importo/.test(h)?' class="num"':''}>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map((v,i)=>`<td${/Ore|Punt|m²|LQR|Consumo|Quantità|Importo/.test(headers[i])?' class="num"':''}>${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">Nessun risultato per i filtri selezionati.</td></tr>`}</tbody></table></div>`}
function panel(title,content,action=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div>${content}</section>`}
function search(){return `<input class="search" id="search" type="search" placeholder="Cerca nel registro…" aria-label="Cerca nel registro" value="${esc(state.query)}">`}
function rowsFilter(rows){return rows.filter(r=>r.join(' ').toLowerCase().includes(state.query.toLowerCase()))}
function bars(items){return `<div class="bars">${items.map(([label,v])=>`<div class="bar-row"><span>${label}</span><div class="bar-track"><div style="width:${v}%"></div></div><span class="num">${fmt(v)}%</span></div>`).join('')}</div>`}
function lineChart(){const a=audits(),current=a.length?a.filter(x=>x.ok).length/a.length*100:0;const endY=Math.max(25,Math.min(145,25+(100-current)*10));const period=state.period==='day'?['08','10','12','14','16','18']:state.period==='week'?['Lun','Mar','Mer','Gio','Ven','Sab']:['Giu','Lug','Ago','Set','Ott','Nov'];return `<svg class="chart" viewBox="0 0 580 190" role="img" aria-label="Andamento dimostrativo degli indici di conformità"><g stroke="#e8eef4">${[25,65,105,145].map(y=>`<path d="M40 ${y}H555"/>`).join('')}</g><g fill="#718399" font-size="13">${[100,96,92,88].map((v,i)=>`<text x="5" y="${29+i*40}">${v}%</text>`).join('')}${period.map((v,i)=>`<text x="${40+i*100}" y="180">${v}</text>`).join('')}</g><polyline points="45,105 145,85 245,65 345,75 445,48 545,${endY}" fill="none" stroke="#009ed0" stroke-width="3"/><polyline points="45,125 145,105 245,92 345,95 445,78 545,${endY}" fill="none" stroke="#4d79a8" stroke-width="2"/><g fill="#009ed0">${[[45,105],[145,85],[245,65],[345,75],[445,48],[545,endY]].map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="3"/>`).join('')}</g></svg><div class="legend"><span><i></i>Risultato</span><span><i style="background:#4d79a8"></i>Processo</span></div>`}
function calendarDates(){return state.period==='day'?[5]:state.period==='week'?[2,3,4,5,6,7,8]:Array.from({length:30},(_,i)=>i+1)}
function dailyHours(day){const weekday=new Date(2026,10,day).getDay();return weekday===0?0:weekday===6?1+day/20:4+day/4}
function periodHours(day){return (day?[day]:calendarDates()).reduce((sum,d)=>sum+dailyHours(d),0)}
const dayCount=()=>calendarDates().filter(d=>dailyHours(d)>0).length;
function tasks(kind='daily',day){const defs=kind==='periodic'?['Lavaggio meccanizzato pavimenti','Pulizia vetrate interne','Trattamento superfici']:kind==='extra'?['Igienizzazione straordinaria','Disinfestazione','Derattizzazione']:['Pulizia uffici','Disinfezione servizi igienici','Pulizia aree comuni'];return scoped().flatMap(s=>defs.map((title,j)=>{const complete=(s.id+j)%6!==0;return {id:`${kind}-${s.id}-${j}`,s,title,complete,planned:periodHours(day)*(j+1)/6,hours:periodHours(day)*(j+1)/6*(complete?1:.8),time:j===0?'07:00':j===1?'10:30':'14:00',status:complete?'Completata':(s.id+j)%2?'In corso':'Programmata'}}))}
function calendar(){const dates=calendarDates();return panel('Calendario operativo',`<div class="calendar ${state.period==='day'?'single':''}">${state.period==='month'?Array.from({length:6},()=>'<div class="calendar-blank"></div>').join(''):''}${dates.map(d=>{const wd=new Date(2026,10,d).getDay(),work=wd!==0;return `<button class="calendar-day ${work?'':'weekend'}" data-day="${d}"><span>${['Dom','Lun','Mar','Mer','Gio','Ven','Sab'][wd]} ${d}</span><small>${work?fmt(dailyHours(d)*scoped().length)+' h':'Non programmato'}</small></button>`}).join('')}</div><p>Ore programmate dimostrative · Novembre 2026 · sabato con orario ridotto · seleziona un giorno per il dettaglio.</p>`)}
function taskPage(){const kind=state.page==='services'?'daily':state.page;let data=tasks(kind);let count=data.length,done=data.filter(x=>x.complete).length;const hours=data.reduce((a,x)=>a+x.hours,0),planned=data.reduce((a,x)=>a+x.planned,0);
const cards=kpis([['Attività completate',`${done} / ${count}`,'Eseguite / programmate nel periodo'],['Esecuzione',`${fmt(count?done/count*100:0)}%`,'Rapporto sulle attività selezionate'],['Ore erogate',`${fmt(hours)} h`,`su ${fmt(planned)} h programmate`],['Puntualità',`${fmt(count?done/count*100:0)}%`,'Eseguite entro la scadenza / programmate demo']]);
if(state.page==='extra')return cards+panel(state.tab===1?'Ordini di lavoro':state.tab===2?'Registro interventi':'Richieste straordinarie',table(['Riferimento','Sede','Prestazione','Stato','Azione'],rowsFilter([...saved.requests.filter(x=>scoped().some(s=>s.id===x.site)).map(x=>[esc(x.id),esc(locations.find(s=>s.id===x.site).city),esc(x.description),status('Da valutare','warn'),`<button class="row-action" data-detail="${esc(x.id)}">Apri</button>`]),...data.slice(0,12).map((x,i)=>[`ODL-2026-${700+i}`,esc(x.s.city),x.title,status(x.status,x.complete?'':'warn'),`<button class="row-action" data-task="${x.id}">Dettagli</button>`])])),search());
if(state.tab===2&&state.page!=='services')return cards+panel('Prestazioni e frequenze',table(['Prestazione','Frequenza','Ambienti','Riferimento'],(kind==='periodic'?[['Lavaggio meccanizzato pavimenti','Settimanale','Aree comuni','Capitolato · Piano di lavoro'],['Pulizia vetrate interne','Mensile','Uffici e accessi','Capitolato · Piano di lavoro'],['Trattamento superfici','Mensile','Ambienti assegnati','Capitolato · Piano di lavoro']]:[['Pulizia uffici','Lunedì – venerdì','Uffici','Programmazione per sede'],['Disinfezione servizi igienici','Lunedì – venerdì','Servizi igienici','Programmazione per sede'],['Pulizia aree comuni','Lunedì – venerdì','Aree comuni','Programmazione per sede']])));
return cards+(state.tab===0?calendar():'')+`<div class="two-col">${panel(state.tab===1?'Registro di esecuzione':'Piano delle attività',table(['Sede','Prestazione','Orario','Stato','Azione'],rowsFilter(data.map(x=>[esc(x.s.city),x.title,x.time,status(x.status,x.complete?'':'warn'),`<button class="row-action" data-task="${x.id}">Apri</button>`]))),search())}${panel('Copertura per cluster',bars(clusters.map((c,i)=>{const a=data.filter(x=>x.s.cluster===i+1);return [`Cluster ${i+1}`,a.length?a.filter(x=>x.complete).length/a.length*100:0]}))+`<p>Attività eseguite rispetto alle programmate. Il calendario e il registro rispettano il periodo selezionato.</p>`)}</div>`}
function services(){if(state.tab===0)return taskPage();if(state.tab===1)return kpis([['Sedi',scoped().length,'Anagrafica contrattuale'],['Cluster',new Set(scoped().map(s=>s.cluster)).size,'Ambiti territoriali'],['Ambienti','—','Consistenze da importare'],['Superficie totale','—','m² · dato non disponibile']])+panel('Sedi, ambienti e superfici',table(['Sede','Indirizzo','Cluster','Superficie m²','Azione'],rowsFilter(scoped().map(s=>[esc(s.city),esc(s.address),s.cluster,'—',`<button class="row-action" data-site="${s.id}">Scheda sede</button>`]))),search());if(state.tab===2)return panel('Richieste, segnalazioni e interventi',table(['Ticket','Sede','Segnalazione','Stato','Azione'],rowsFilter([...saved.requests.filter(x=>scoped().some(s=>s.id===x.site)).map(x=>[esc(x.id),esc(locations.find(s=>s.id===x.site).city),esc(x.description),status('Da valutare','warn'),`<button class="row-action" data-detail="${esc(x.id)}">Apri</button>`]),...scoped().slice(0,5).map((s,i)=>[`SEG-2026-${110+i}`,esc(s.city),['Rifornimento materiale igienico','Verifica dosatore','Ripristino area ingresso'][i%3],status(i%2?'In lavorazione':'Risolta',i%2?'warn':''),`<button class="row-action" data-site="${s.id}">Dettagli</button>`])])),search())+`<a href="#emergency" class="outline">Apri gestione emergenze →</a>`;
return panel('Forniture igieniche · GSP4PFE',`<p>Monitoraggio dimostrativo di scorte e rifornimenti. Sistema GSP4PFE non connesso.</p>`+table(['Prodotto','Giacenza','Soglia minima','Disponibilità','Azione'],[['Carta igienica','120 confezioni','40 confezioni',status('Disponibile'),'<button class="row-action" data-order="Carta igienica">Richiedi rifornimento</button>'],['Sapone mani','18 taniche','20 taniche',status('Sotto soglia','warn'),'<button class="row-action" data-order="Sapone mani">Richiedi rifornimento</button>'],['Asciugamani carta','85 confezioni','30 confezioni',status('Disponibile'),'<button class="row-action" data-order="Asciugamani carta">Richiedi rifornimento</button>']]))}
function people(){return scoped().map((s,i)=>({s,name:['M. Serra','A. Piras','F. Sanna','G. Melis','L. Manca','R. Contini'][i%6],code:`OP-${String(s.id).padStart(3,'0')}`,present:saved.attendance[s.id]!==undefined?saved.attendance[s.id]:s.id%7!==0,hours:4*dayCount()}))}
function staff(){let p=people(),present=p.filter(x=>x.present).length;let cards=kpis([['Organico effettivo',`${present} / ${p.length}`,'Presenti / dotazione minima demo'],['Ore erogate',`${fmt(present*4*dayCount())} h`,`su ${fmt(p.length*4*dayCount())} h programmate`],['Copertura organico',`${fmt(p.length?present/p.length*100:0)}%`,'Addetti presenti / minimo'],['Assenze da coprire',p.length-present,'Sostituzioni ancora da assegnare']]);
if(state.tab===0)return cards+panel('Operatori e assegnazioni',table(['Operatore demo','Matricola','Sede assegnata','Cluster','Stato'],rowsFilter(p.map(x=>[x.name,x.code,esc(x.s.city),x.s.cluster,status(x.present?'Presente':'Assente',x.present?'':'warn')]))),search());
if(state.tab===1)return cards+panel('Registro giornaliero e timbrature digitali',`<p>Le timbrature registrate qui sono simulazioni salvate in questo browser.</p>`+table(['Operatore','Sede','Turno','Ore programmate','Presenza','Azione'],rowsFilter(p.map(x=>[x.name,esc(x.s.city),'07:00–11:00','4 h',status(x.present?'Presente':'Assente',x.present?'':'warn'),`<button class="row-action" data-attendance="${x.s.id}">${x.present?'Registra uscita':'Registra ingresso'}</button>`]))),search());
if(state.tab===2)return cards+panel('Copertura del servizio per cluster',bars(clusters.map((c,i)=>{let a=p.filter(x=>x.s.cluster===i+1);return [`Cluster ${i+1}`,a.length?a.filter(x=>x.present).length/a.length*100:0]})))+panel('Sostituzioni e variazioni',table(['Sede','Operatore assente','Sostituzione','Comunicazione'],p.filter(x=>!x.present).map(x=>[esc(x.s.city),x.name,status('Da assegnare','warn'),'<button class="row-action" data-request="Sostituzione personale">Richiedi sostituzione</button>'])));
return cards+panel('Verifica divise, tesserini e DPI',table(['Operatore','Divisa','Tesserino','DPI','Azione'],rowsFilter(p.map(x=>[x.name,status('Conforme'),status('Presente'),status(x.s.id%5?'Completi':'Da integrare',x.s.id%5?'':'warn'),`<button class="row-action" data-check="${x.code}">Verifica dotazioni</button>`]))),search())}
function audits(type='result'){return scoped().flatMap(s=>[0,1].map((v,j)=>({s,id:`${type==='result'?'R':'P'}-${s.id}-${j}`,score:94+(s.id+j)%6,ok:(s.id+j)%9!==0,day:j?'03/11/2026':'05/11/2026'})))}
function quality(){let a=audits(),ok=a.filter(x=>x.ok).length;let cards=kpis([['Audit effettuati',`${a.length} / ${a.length+scoped().length}`,'Svolti / programmati · demo'],['Conformità risultato',`${fmt(a.length?ok/a.length*100:0)}%`,'Check-list conformi / eseguite'],['Conformità processo',`${fmt(a.length?ok/a.length*100:0)}%`,'Indice aggregato · demo'],['Non conformità aperte',a.length-ok,'Azioni da completare · demo']]);
if(state.tab===0)return cards+`<div class="two-col">${panel('Andamento degli indici aggregati',lineChart())}${panel('Configurazione controlli · 36 mesi',`<div class="detail-grid"><dt>Controlli di risultato</dt><dd><strong>3.312 audit</strong></dd><dt>Controlli di processo</dt><dd><strong>1.248 audit</strong></dd><dt>Fonte</dt><dd>Bozza PFE, riportata nel documento</dd></div><p>Riferimenti di configurazione complessivi, distinti dai controlli eseguiti nel periodo selezionato.</p><a class="row-action" href="#reports">Verifiche in contraddittorio con Abbanoa →</a>`)}</div>`+panel('Ultime non conformità',ncTable(a));
if(state.tab===1||state.tab===2){let type=state.tab===1?'result':'process',data=audits(type);return cards+`<div class="notice">I punteggi delle singole check-list sono distinti dall’indice aggregato di conformità. Soglie LQA${type==='process'?'-P':''} e pesi contrattuali sono da configurare: l’esito qui è dimostrativo.</div>`+panel(type==='result'?'Check-list di risultato · LQR / LQA':'Check-list di processo · LQR-P / LQA-P',table(['Data','Sede','Check-list','Punteggio LQR','LQA applicabile','Esito','Azione'],rowsFilter(data.map(x=>[x.day,esc(x.s.city),x.id,fmt(x.score)+'/100','Da configurare',status(x.ok?'Conforme demo':'Non conforme demo',x.ok?'':'bad'),`<button class="row-action" data-audit="${x.id}">Check-list</button>`]))),search())}
if(state.tab===3)return cards+panel('Campionamento e accettazione statistica',`<p>Terzo livello della metodologia PFE: l’accettazione del campione non coincide con il punteggio di una check-list né con la percentuale aggregata di conformità.</p>`+table(['Parametro','Configurazione'],[['Unità di controllo','Ambienti / elementi da censire per sede'],['Numerosità del campione','Da definire secondo metodologia PFE'],['LQA / LQA-P','Soglie e pesi da acquisire'],['Criterio di accettazione / rifiuto','Da importare dalla metodologia contrattuale'],['Esito statistico','Non calcolabile prima della configurazione']]))+`<div class="notice">La “Bozza relazione.pdf” citata nel documento non è allegata: nessuna soglia statistica è stata dedotta dai mockup.</div>`;
return cards+panel('Registro non conformità e azioni correttive',ncTable(a),'<button class="outline" data-request="Non conformità">Nuova non conformità</button>')}
function ncTable(a){return table(['Data','Sede','Ambiente','Non conformità','Stato','Azione'],a.filter(x=>!x.ok).map(x=>[x.day,esc(x.s.city),'Area comune','Esecuzione da verificare',status('Aperta','bad'),`<button class="row-action" data-audit="${x.id}">Evidenze e azioni</button>`]))}
const courses=[['Sicurezza generale e specifica','Obbligatorio','8 h','20/11/2026'],['Prodotti e procedure di disinfezione','Operativo','4 h','12/11/2026'],['Attrezzature e macchinari FIMAP','Specialistico','4 h','18/11/2026'],['CAM e gestione ambientale','Ambientale','2 h','25/11/2026']];
function training(){let p=people();let cards=kpis([['Addetti in perimetro',p.length,'Anagrafica formativa demo'],['Corsi previsti',courses.length,'Piano formativo dimostrativo'],['Ore per addetto','18 h','Totale del percorso previsto'],['Attestati effettivi','—','Archivio documentale non connesso']]);if(state.tab===0)return cards+panel('Piano formativo e addestramento',table(['Corso','Tipologia','Durata','Prossima sessione','Azione'],rowsFilter(courses.map((x,i)=>[...x,`<button class="row-action" data-course="${i}">Programma</button>`]))),search());if(state.tab===1)return cards+panel('Anagrafica formativa per addetto',table(['Addetto demo','Sede','Corsi completati','Ore formazione','Stato'],rowsFilter(p.map((x,i)=>[x.name,esc(x.s.city),`${i%2?3:4} / 4`,`${i%2?14:18} h`,status(i%2?'Da completare':'Aggiornata',i%2?'warn':'')]))),search());if(state.tab===2)return cards+panel('Test di valutazione e attestati',table(['Corso','Test','Attestato','Azione'],courses.map((x,i)=>[x[0],'Simulazione disponibile','Nessun documento effettivo',`<button class="row-action" data-course="${i}">Apri test demo</button>`])));return cards+panel('Scadenziario formazione',table(['Scadenza','Corso','Destinatari','Stato'],courses.map(x=>[x[3],x[0],`${p.length} addetti`,status('Pianificato','neutral')])))}
function sustainability(){let sites=scoped().length;let cards=kpis([['Consumo idrico','0,82 L/m²','Valore dimostrativo del periodo'],['Consumo energetico','0,34 kWh/m²','Valore dimostrativo del periodo'],['Consumo detergenti','0,012 L/m²','Valore dimostrativo del periodo'],['Emissioni CO₂e',`${fmt(sites*dayCount()*0.17)} kg`,'Stima demo · fattori da configurare']]);if(state.tab===0)return cards+`<div class="two-col">${panel('Consumi per sede',table(['Sede','Acqua L','Energia kWh','Detergenti L'],rowsFilter(scoped().map(s=>[esc(s.city),fmt(dayCount()*8.2),fmt(dayCount()*3.4),fmt(dayCount()*.12)]))),search())}${panel('Indicatori ambientali',`<p>Intensità normalizzate per superficie. Valori e superfici dimostrativi; nessuna misura di campo disponibile.</p>`+bars([['Acqua / target demo',82],['Energia / target demo',68],['Detergenti / target demo',60]])+`<p>I target mostrati sono esempi di configurazione, non soglie contrattuali.</p>`)}</div>`;
if(state.tab===1)return cards+panel('Registro prodotti e conformità CAM',table(['Prodotto','Conformità','Scheda tecnica','Sicurezza','Azione'],[['Detergente multiuso concentrato',status('Da documentare','warn'),'Non allegata','SDS non allegata','<button class="row-action" data-product="Detergente multiuso">Scheda prodotto</button>'],['Disinfettante superfici',status('Da documentare','warn'),'Non allegata','SDS non allegata','<button class="row-action" data-product="Disinfettante superfici">Scheda prodotto</button>']]))+`<div class="notice">Conformità CAM e certificazioni devono essere verificate sui prodotti effettivamente impiegati.</div>`;
if(state.tab===2)return cards+panel('Parco macchinari FIMAP',table(['Matricola demo','Sede','Macchinario','Ore utilizzo','Manutenzione'],rowsFilter(scoped().map(s=>[`FM-${String(s.id).padStart(3,'0')}`,esc(s.city),'Lavasciuga FIMAP',fmt(dayCount()*2)+' h',status(s.id%5?'Regolare':'Da pianificare',s.id%5?'':'warn')]))),search());
if(state.tab===3)return cards+panel('Raccolta differenziata · NANDO',`<p>Registro dimostrativo. Sistema NANDO non connesso.</p>`+table(['Sede','Frazione','Quantità kg','Errori conferimento','Azione'],rowsFilter(scoped().map(s=>[esc(s.city),s.id%2?'Carta e cartone':'Plastica',fmt(dayCount()*1.2),s.id%9===0?'1':'0',`<button class="row-action" data-request="Conferimento rifiuti">Registra</button>`]))),search());return cards+panel('Manutenzione e sostituzione filtri HEPA',table(['Macchinario','Sede','Ultima verifica','Prossima scadenza','Stato'],scoped().map(s=>[`Aspiratore HP-${s.id}`,esc(s.city),'01/10/2026','01/12/2026',status('Pianificata','neutral')])))}
function reports(){const data=scoped().map((s,i)=>({s,id:`VV-2026-${100+s.id}`,date:i%2?'03/11/2026':'05/11/2026',ok:s.id%6!==0}));let cards=kpis([['Verbali nel periodo',data.length,'Registri dimostrativi'],['Verifiche conformi',data.filter(x=>x.ok).length,'Esito della verifica DEC'],['Contestazioni',data.filter(x=>!x.ok).length,'Da gestire in contraddittorio'],['Penali applicate','—','Nessuna penale effettiva registrata']]);if(state.tab===0)return cards+panel('Storico verifiche per sede e data',table(['Data','Verbale','Sede','Esito','Sottoscrizioni','Azione'],rowsFilter(data.map(x=>[x.date,x.id,esc(x.s.city),status(x.ok?'Conforme':'Con osservazioni',x.ok?'':'warn'),'Esempio · non firmato',`<button class="row-action" data-report="${x.s.id}">Apri verbale</button>`]))),search())+`<div class="notice">Questa sezione raccoglie le verifiche del DEC in contraddittorio con Abbanoa (art. 18). Le check-list di autocontrollo PFE si trovano in <a href="#quality">Controllo Qualità</a>.</div>`;if(state.tab===1)return cards+panel('Contestazioni, osservazioni e controdeduzioni',table(['Verbale','Sede','Osservazione','Controdeduzione','Stato'],data.filter(x=>!x.ok).map(x=>[x.id,esc(x.s.city),'Verifica della frequenza eseguita','In attesa di riscontro PFE',status('Aperta','warn')])));return cards+panel('Potenziali inadempimenti e penali',table(['Riferimento','Sede','Potenziale inadempimento','Importo €','Stato'],data.filter(x=>!x.ok).map(x=>[x.id,esc(x.s.city),'Frequenza da verificare','—',status('Da accertare','warn')])))+`<p class="scope-caption">Gli importi richiedono contestazione e valutazione contrattuale; nessun automatismo di applicazione penali.</p>`}
function issues(){return [...saved.issues,...scoped().slice(0,3).map((s,i)=>({id:`EM-2026-${147+s.id}`,site:s.id,description:['Allagamento rilevato','Ripristino igienico urgente','Sversamento accidentale'][i],priority:i===0?'Alta':'Media',step:i===0?6:3,source:i===0?'Sensore AI · simulazione':'Segnalazione manuale',date:'05/11/2026, 09:14'}))].filter((x,i,all)=>all.findIndex(v=>v.id===x.id)===i).filter(x=>scoped().some(s=>s.id===x.site))}
let selectedIssue=null;
const steps=['Segnalazione ricevuta','Ticket aperto','Validazione','Assegnazione priorità','Attivazione squadra emergenze','Comunicazione luogo da raggiungere','Partenza operatori','Arrivo sul posto','Messa in sicurezza','Risoluzione intervento','Chiusura ticket / report finale'];
function emergency(){const data=issues();let issue=data.find(x=>x.id===selectedIssue)||data[0];let cards=kpis([['Emergenze aperte',data.filter(x=>x.step<10).length,'Nel perimetro selezionato · demo'],['Tempo presa in carico','4 min','Esempio · target demo ≤ 6 min'],['Tempo risoluzione','42 min','Esempio · nessuna misura reale'],['Squadre operative',Math.min(3,scoped().length),'Disponibilità dimostrativa']]);if(state.tab===1)return cards+panel('Squadre e attivazioni',table(['Squadra','Composizione','Mezzo / attrezzature','Stato','Azione'],[1,2,3].map((x,i)=>[`Squadra E-0${x}`,'2 operatori + 1 caposquadra','Furgone · kit emergenza · DPI',status(i===0?'In trasferimento':'Disponibile',i===0?'warn':''),'<button class="row-action" data-request="Attivazione squadra">Attiva</button>'])));if(state.tab===2)return cards+panel('Registro comunicazioni',table(['Ora','Ticket','Mittente','Comunicazione'],data.flatMap(x=>[['09:15',esc(x.id),'Sistema demo','Ticket aperto e notifica predisposta'],['09:18',esc(x.id),'Caposquadra demo','Squadra assegnata, attivazione simulata']])));if(!issue)return cards+panel('Emergenze',`<div class="empty">Nessuna emergenza nel perimetro selezionato. Puoi creare una segnalazione dimostrativa.</div>`);
const s=locations.find(s=>s.id===issue.site);return cards+panel('Registro emergenze',table(['Ticket','Sede','Evento','Priorità','Stato','Azione'],data.map(x=>[esc(x.id),esc(locations.find(s=>s.id===x.site).city),esc(x.description),status(x.priority,x.priority==='Alta'?'bad':'warn'),status(x.step>=10?'Risolta':'In gestione',x.step>=10?'':'warn'),`<button class="row-action" data-issue="${esc(x.id)}">Segui iter</button>`])))+`<div class="two-col"><div>${panel(esc(issue.description),`<dl class="detail-grid"><dt>Ticket</dt><dd>${esc(issue.id)}</dd><dt>Sede</dt><dd>${esc(s.city)}</dd><dt>Indirizzo</dt><dd>${esc(s.address)}</dd><dt>Area / ambiente</dt><dd>Piano terra · Area archivio (demo)</dd><dt>Data / ora</dt><dd>${esc(issue.date)}</dd><dt>Origine</dt><dd>${esc(issue.source)}</dd><dt>Priorità</dt><dd>${status(issue.priority,issue.priority==='Alta'?'bad':'warn')}</dd><dt>Squadra assegnata</dt><dd>E-03 · 2 operatori + caposquadra</dd><dt>Mezzo / attrezzature</dt><dd>Kit allagamento, aspiraliquidi, DPI</dd><dt>ETA dimostrativo</dt><dd>18 minuti dalla partenza</dd></dl>${siteMap(s)}`)}${panel('Ticket e comunicazioni',table(['Ora','Mittente','Messaggio'],[['09:15','Sistema demo','Apertura ticket di emergenza'],['09:18','Caposquadra demo','Squadra confermata e luogo condiviso'],['09:21','Operatore demo','Partenza da sede operativa']]))}${panel('Esito e chiusura',(issue.step>=10?`<p>${esc(issue.outcome||'Intervento completato nella simulazione.')}</p>${status('Risolta')}<p>Follow-up: verifica del ripristino e manutenzione da pianificare.</p>`:`<p>Causa, azioni eseguite, evidenze fotografiche, tempo di risoluzione e follow-up saranno raccolti nel report di chiusura.</p><button class="outline" data-close-issue="${esc(issue.id)}">Compila report finale</button>`)+evidenceGallery())}</div>${panel('Workflow di gestione',`<ol class="workflow">${steps.map((x,i)=>`<li class="${i<issue.step?'done':i===issue.step?'current':''}">${x}<small>${i<issue.step?'Completato nella simulazione':i===issue.step?'Fase corrente':'In attesa'}</small></li>`).join('')}</ol>${issue.step<10?`<button class="primary" style="margin-top:20px" data-advance="${esc(issue.id)}">Avanza fase demo →</button>`:''}<p>Workflow dimostrativo: nessuna squadra viene contattata e nessuna notifica esterna viene inviata.</p>`)}</div>`}
function render(){nav();document.body.classList.toggle('dashboard',state.page!=='home');$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');if(state.page==='home')$('#main').innerHTML=home();else{const m=modules[state.page];const action=state.page==='emergency'?'Nuova emergenza':state.page==='extra'?'Nuova richiesta':state.page==='services'?'Nuova segnalazione':null;$('#main').innerHTML=`<div class="page-title"><div><a class="breadcrumb" href="#home">Panoramica / ${m.short}</a><h1>${m.name}</h1><p>${m.description}</p></div><div>${action?`<button class="primary" id="new-record">+ ${action}</button>`:'<button class="outline" id="export">Esporta CSV</button>'}</div></div>${filters()}<div class="tabs" role="tablist">${m.tabs.map((t,i)=>`<button role="tab" aria-selected="${state.tab===i}" class="${state.tab===i?'active':''}" data-tab="${i}">${t}</button>`).join('')}</div><div class="screen-content">${['daily','periodic','extra'].includes(state.page)?taskPage():state.page==='services'?services():state.page==='staff'?staff():state.page==='quality'?quality():state.page==='training'?training():state.page==='sustainability'?sustainability():state.page==='reports'?reports():emergency()}</div><p class="scope-caption">Dati operativi dimostrativi · ${esc(scopeName())} · ${state.period==='day'?'5 novembre':state.period==='week'?'2–8 novembre':'Novembre'} 2026</p>`}bind();enhanceSites();$('.landing-nav')?.classList.remove('open')}
function route(){const key=location.hash.slice(1)||'home';if(['activities','information'].includes(key)){state.page='home';state.tab=0;render();requestAnimationFrame(()=>document.getElementById(key)?.scrollIntoView({behavior:'smooth',block:'start'}));return}state.page=modules[key]?key:'home';state.tab=0;state.query='';render();window.scrollTo(0,0)}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function modal(title,body){$('#modal-body').innerHTML=`<h2 id="modal-title">${title}</h2>${body}`;$('#modal').setAttribute('aria-labelledby','modal-title');$('#modal').showModal();enhanceSites($('#modal'))}
function siteOptions(){return scoped().map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}
function newRecord(type='request',prefill=''){modal(type==='emergency'?'Nuova emergenza':'Nuova registrazione',`<p class="scope-caption">Simulazione salvata solo in questo browser. Nessun invio a PFE o Abbanoa.</p><form id="record-form"><label>Sede<select name="site" required>${siteOptions()}</select></label><label>Descrizione<textarea name="description" required minlength="5" rows="3">${esc(prefill)}</textarea></label>${type==='emergency'?'<label>Priorità<select name="priority"><option>Alta</option><option>Media</option><option>Bassa</option></select></label>':''}<div class="form-actions"><button type="button" class="outline" onclick="document.querySelector('#modal').close()">Annulla</button><button class="primary">Salva simulazione</button></div></form>`);$('#record-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.site=+d.site;d.id=`${type==='emergency'?'EM':'RIC'}-DEMO-${Date.now().toString().slice(-6)}`;if(type==='emergency'){d.step=0;d.source='Segnalazione manuale · demo';d.date=new Date().toLocaleString('it-IT');saved.issues.unshift(d);selectedIssue=d.id}else saved.requests.unshift(d);persist();$('#modal').close();render();toast('Registrazione demo salvata nel browser.')}}
function getIssue(id){let found=saved.issues.find(x=>x.id===id);if(!found){found=issues().find(x=>x.id===id);if(found){saved.issues.push({...found});found=saved.issues.at(-1)}}return found}
function bind(){document.querySelectorAll('[data-day]').forEach(el=>el.onclick=()=>{const d=+el.dataset.day,wd=new Date(2026,10,d).getDay();modal('Programmazione · '+d+' novembre 2026',wd===0?'<p>Nessuna attività ordinaria programmata la domenica.</p>':`<p>Ore programmate: <strong>${fmt(dailyHours(d)*scoped().length)} h</strong>${wd===6?' · Sabato con orario ridotto':''}</p>`+table(['Sede','Prestazione','Orario','Ore programmate'],tasks(state.page==='periodic'?'periodic':'daily',d).map(x=>[esc(x.s.city),x.title,x.time,fmt(x.planned)+' h'])))});['cluster','site','period'].forEach(id=>{let el=$('#'+id);if(el)el.onchange=e=>{state[id]=e.target.value;if(id==='cluster')state.site='all';state.query='';render()}});document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{state.tab=+el.dataset.tab;state.query='';render()});if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;state.query=e.target.value;render();$('#search').focus();try{$('#search').setSelectionRange(pos,pos)}catch{}};if($('#new-record'))$('#new-record').onclick=()=>newRecord(state.page==='emergency'?'emergency':'request');if($('#export'))$('#export').onclick=exportCSV;
document.querySelectorAll('[data-site]').forEach(el=>el.onclick=()=>{const s=locations.find(s=>s.id===+el.dataset.site);modal('Scheda sede',`<dl class="detail-grid"><dt>Località</dt><dd>${esc(s.city)}</dd><dt>Indirizzo</dt><dd>${esc(s.address)}</dd><dt>Cluster</dt><dd>${s.cluster} · ${clusters[s.cluster-1]}</dd><dt>Ambienti</dt><dd>Da censire</dd><dt>Superfici</dt><dd>Da acquisire dal contratto</dd></dl>`)});
document.querySelectorAll('[data-task]').forEach(el=>el.onclick=()=>{let x=tasks(el.dataset.task.split('-')[0]).find(x=>x.id===el.dataset.task);modal(x.title,`<dl class="detail-grid"><dt>Sede</dt><dd>${esc(x.s.name)}</dd><dt>Orario</dt><dd>${x.time}</dd><dt>Stato</dt><dd>${x.status}</dd><dt>Ore programmate</dt><dd>${fmt(x.planned)} h</dd><dt>Ore erogate</dt><dd>${fmt(x.hours)} h</dd><dt>Evidenze</dt><dd>Nessun allegato reale disponibile</dd></dl><p class="scope-caption">Intervento dimostrativo.</p>`)});
document.querySelectorAll('[data-request]').forEach(el=>el.onclick=()=>newRecord('request',el.dataset.request));document.querySelectorAll('[data-order]').forEach(el=>el.onclick=()=>newRecord('request','Rifornimento: '+el.dataset.order));
document.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>{let x=saved.requests.find(x=>x.id===el.dataset.detail);modal('Dettaglio richiesta',`<p>${esc(x.description)}</p><p>${esc(locations.find(s=>s.id===x.site).name)}</p>${status('Da valutare','warn')}<p class="scope-caption">Registrazione demo locale.</p>`)});
document.querySelectorAll('[data-attendance]').forEach(el=>el.onclick=()=>{let id=+el.dataset.attendance,p=people().find(x=>x.s.id===id);saved.attendance[id]=!p.present;persist();render();toast('Timbratura dimostrativa registrata.')});
document.querySelectorAll('[data-check]').forEach(el=>el.onclick=()=>{modal('Verifica dotazioni · '+el.dataset.check,`<form id="check-form">${['Divisa conforme','Tesserino identificativo presente','Guanti e DPI disponibili','Calzature idonee'].map(t=>`<label class="check"><input type="checkbox" required>${t}</label>`).join('')}<button class="primary">Completa verifica demo</button></form>`);$('#check-form').onsubmit=e=>{e.preventDefault();$('#modal').close();toast('Verifica demo completata; nessun registro aziendale modificato.')}});
document.querySelectorAll('[data-audit]').forEach(el=>el.onclick=()=>{modal('Check-list · '+el.dataset.audit,`<p>Punteggio dimostrativo della singola verifica. Pesi e soglia LQA contrattuale da configurare.</p>${table(['Elemento di controllo','Esito demo'],[['Pavimenti e superfici','Conforme'],['Servizi igienici','Conforme'],['Frequenza e procedura','Da verificare']])}<h3>Azione correttiva</h3><p>Ripetere la prestazione e programmare una verifica di efficacia.</p><h3>Evidenze fotografiche</h3><p>Nessuna fotografia operativa allegata.</p><button class="outline" data-request="Azione correttiva">Registra azione correttiva</button>`);$('#modal [data-request]').onclick=()=>{$('#modal').close();newRecord('request','Azione correttiva per '+el.dataset.audit)}});
document.querySelectorAll('[data-course]').forEach(el=>el.onclick=()=>{const c=courses[+el.dataset.course];modal(c[0],`<p>${c[1]} · ${c[2]} · Sessione prevista ${c[3]}</p><p>Programma: procedure operative, corretta applicazione e verifica dell’apprendimento.</p><form id="quiz"><label>Prima di utilizzare un prodotto, quale documento deve essere consultato?<select required><option value="">Seleziona risposta</option><option value="correct">Scheda tecnica e scheda di sicurezza</option><option value="wrong">Solo l’etichetta del prezzo</option></select></label><button class="primary">Verifica risposta</button><p id="quiz-result" role="status"></p></form><p class="scope-caption">Test esemplificativo; non rilascia attestati.</p>`);$('#quiz').onsubmit=e=>{e.preventDefault();$('#quiz-result').textContent=$('#quiz select').value==='correct'?'Risposta corretta. Il test demo è completato.':'Risposta non corretta. Riprova.'}});
document.querySelectorAll('[data-product]').forEach(el=>el.onclick=()=>modal(esc(el.dataset.product),'<p>Registro prodotti · scheda tecnica, SDS e documentazione CAM da acquisire dal fornitore.</p><p>Nessuna dichiarazione di conformità è disponibile in questa demo.</p>'));
document.querySelectorAll('[data-report]').forEach(el=>el.onclick=()=>{let s=locations.find(x=>x.id===+el.dataset.report);modal('Verbale di verifica del servizio',`<p>VV-2026-${100+s.id} · 05/11/2026 · Art. 18</p><dl class="detail-grid"><dt>Sede</dt><dd>${esc(s.name)}</dd><dt>Ambienti ispezionati</dt><dd>Uffici, servizi igienici, aree comuni</dd><dt>Esito demo</dt><dd>${s.id%6?'Conforme':'Con osservazioni'}</dd><dt>Verificatore DEC</dt><dd>Da sottoscrivere</dd><dt>Referente PFE</dt><dd>Da sottoscrivere</dd><dt>Osservazioni</dt><dd>${s.id%6?'Nessuna osservazione nell’esempio':'Frequenza da verificare'}</dd><dt>Controdeduzioni</dt><dd>Da acquisire, se applicabili</dd></dl><p class="scope-caption">Facsimile dimostrativo privo di valore contrattuale e firme.</p><button class="outline" id="print-report">Stampa facsimile</button>`);$('#print-report').onclick=()=>window.print()});
document.querySelectorAll('[data-issue]').forEach(el=>el.onclick=()=>{selectedIssue=el.dataset.issue;render()});document.querySelectorAll('[data-advance]').forEach(el=>el.onclick=()=>{const x=getIssue(el.dataset.advance);if(x.step>=9){closeIssue(x.id);return}x.step++;persist();render();toast('Workflow dimostrativo aggiornato.')});document.querySelectorAll('[data-close-issue]').forEach(el=>el.onclick=()=>closeIssue(el.dataset.closeIssue));}
function closeIssue(id){const x=getIssue(id);modal('Report finale emergenza',`<form id="close-form"><label>Causa e azioni eseguite<textarea name="outcome" required minlength="10" rows="4"></textarea></label><label>Follow-up<textarea name="followup" rows="2"></textarea></label><p class="scope-caption">Chiusura dimostrativa, salvata solo in questo browser.</p><button class="primary">Chiudi ticket demo</button></form>`);$('#close-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);x.outcome=f.get('outcome')+' Follow-up: '+f.get('followup');x.step=10;persist();$('#modal').close();render();toast('Ticket demo chiuso.')}}
function exportCSV(){const tableEl=$('main table');if(!tableEl){toast('Apri un registro per esportare i dati.');return}let rows=[...tableEl.rows].map(row=>[...row.cells].map(c=>'"'+c.innerText.replace(/"/g,'""')+'"').join(';')).join('\r\n');const blob=new Blob(['\uFEFF'+rows],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`abbanoa-${state.page}-demo.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#menu').onclick=()=>{if(state.page==='home'){const open=$('.landing-nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));return}const open=$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};$('#access').onclick=loginModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});window.addEventListener('hashchange',route);console.assert(locations.length===36,'36 sedi attese');console.assert(clusters.length===5,'5 cluster attesi');


let selectPopup=null;
function closeSelect(){if(!selectPopup)return;const {pop,trigger}=selectPopup;try{pop.hidePopover()}catch{}pop.remove();trigger.setAttribute('aria-expanded','false');selectPopup=null}
function enhanceSites(root=document){if(root===document)closeSelect();root.querySelectorAll('select:not([data-enhanced])').forEach(native=>{native.dataset.enhanced='true';native.classList.add('native-fallback');native.tabIndex=-1;const wrap=document.createElement('div');wrap.className='unified-select';native.parentNode.insertBefore(wrap,native);wrap.append(native);const trigger=document.createElement('button');trigger.type='button';trigger.className='unified-trigger';const label=document.querySelector('label[for="'+native.id+'"]')?.textContent||native.closest('label')?.childNodes[0]?.textContent||native.name||'Seleziona';trigger.setAttribute('aria-label',label.trim());trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-haspopup','dialog');function sync(){trigger.innerHTML='<span>'+esc(native.selectedOptions[0]?.text||'Seleziona')+'</span><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 9 6 6 6-6"/></svg>'}sync();wrap.append(trigger);native.addEventListener('change',sync);trigger.onclick=()=>{if(selectPopup?.trigger===trigger){closeSelect();return}closeSelect();const pop=document.createElement('div');pop.className='unified-popup';pop.setAttribute('popover','auto');pop.setAttribute('role','dialog');pop.setAttribute('aria-label',label.trim());pop.innerHTML='<input type="search" aria-label="Cerca opzione" placeholder="Cerca…"><div class="unified-options"></div>';document.body.append(pop);const input=pop.querySelector('input'),list=pop.querySelector('.unified-options');function options(){const opts=[...native.options].filter(o=>o.text.toLowerCase().includes(input.value.toLowerCase()));list.innerHTML=opts.length?opts.map(o=>'<button type="button" class="unified-option '+(o.selected?'selected':'')+'" data-value="'+esc(o.value)+'"><span>'+esc(o.text)+'</span>'+(o.selected?'✓':'')+'</button>').join(''):'<p>Nessun risultato</p>';list.querySelectorAll('button').forEach(b=>b.onclick=()=>{native.value=b.dataset.value;closeSelect();native.dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('[data-select-return="'+native.id+'"]')?.focus()})}options();selectPopup={pop,trigger};const rect=trigger.getBoundingClientRect();const width=Math.min(Math.max(rect.width,290),innerWidth-24);pop.style.width=width+'px';pop.style.left=Math.max(12,Math.min(rect.left,innerWidth-width-12))+'px';const below=innerHeight-rect.bottom-16;const above=rect.top-16;const height=Math.min(360,Math.max(below,above));pop.style.maxHeight=height+'px';pop.style.top=(below>=Math.min(280,above)?rect.bottom+8:Math.max(12,rect.top-height-8))+'px';pop.showPopover();input.focus();pop.addEventListener('toggle',e=>{if(e.newState==='closed'&&selectPopup?.pop===pop)closeSelect()});pop.onkeydown=e=>{const buttons=[...list.querySelectorAll('button')];const i=buttons.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();closeSelect();trigger.focus()}if(e.key==='ArrowDown'){e.preventDefault();buttons[Math.min(i+1,buttons.length-1)]?.focus()}if(e.key==='ArrowUp'){e.preventDefault();buttons[Math.max(i-1,0)]?.focus()}};input.oninput=options;trigger.setAttribute('aria-expanded','true')};trigger.dataset.selectReturn=native.id})}
addEventListener('resize',closeSelect);addEventListener('scroll',e=>{if(selectPopup&&!selectPopup.pop.contains(e.target))closeSelect()},true);
function siteMap(s){const q=encodeURIComponent(s.address+', '+s.city+', Sardegna, Italia');return `<section class="emergency-location"><div class="location-title">${icon('home')}<div><strong>${esc(s.city)}</strong><p>${esc(s.address)}</p><small>Cluster ${s.cluster} · Piano terra / Area archivio (demo)</small></div></div><iframe title="Mappa della sede ${esc(s.city)}" src="https://maps.google.com/maps?q=${q}&output=embed" loading="lazy" referrerpolicy="no-referrer"></iframe><a class="outline" href="https://www.google.com/maps/search/?api=1&query=${q}" target="_blank" rel="noopener">Apri localizzazione sulla mappa ↗</a><small>Posizione ricercata tramite indirizzo della sede. Ambiente interno dimostrativo.</small></section>`}
function evidenceGallery(){return `<section class="evidence"><h3>Evidenze fotografiche</h3><p>Tre immagini dimostrative dell’intervento, ispirate alla reference.</p><div class="evidence-grid">${['Allagamento rilevato','Riparazione raccordo','Area ripristinata'].map((label,i)=>`<button type="button" class="evidence-photo" onclick="openEvidence(${i+1})"><img src="assets/evidence-${i+1}.webp" alt="${label} · immagine dimostrativa"><span>${label}</span></button>`).join('')}</div></section>`}
function openEvidence(i){modal('Evidenza fotografica · esempio',`<img class="evidence-full" src="assets/evidence-${i}.webp" alt="Evidenza dimostrativa dell’intervento"><p>Immagine generata a scopo dimostrativo; non documenta un’emergenza reale.</p>`)}
function loginModal(){modal('Accesso al portale',`<p>Inserisci le credenziali per accedere all’ambiente dimostrativo.</p><form id="login-form"><label for="login-email">Email<input id="login-email" name="email" type="email" autocomplete="username" placeholder="nome@azienda.it" required></label><label for="login-password">Password<div class="password-wrap"><input id="login-password" name="password" type="password" autocomplete="current-password" required><button type="button" id="toggle-password" aria-label="Mostra password">Mostra</button></div></label><div class="login-demo">Credenziali demo:<br><strong>demo@abbanoa.local</strong> · <strong>Demo2026!</strong></div><p id="login-feedback" role="status"></p><button class="primary login-submit">Accedi</button></form><p class="scope-caption">Autenticazione aziendale non collegata. Utilizza esclusivamente le credenziali dimostrative indicate.</p>`);$('#toggle-password').onclick=()=>{const input=$('#login-password');const show=input.type==='password';input.type=show?'text':'password';$('#toggle-password').textContent=show?'Nascondi':'Mostra';$('#toggle-password').setAttribute('aria-label',show?'Nascondi password':'Mostra password')};$('#login-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('email')==='demo@abbanoa.local'&&f.get('password')==='Demo2026!'){$('#modal').close();toast('Accesso dimostrativo effettuato.');location.hash='services'}else $('#login-feedback').textContent='Credenziali non riconosciute. Usa l’account demo indicato.'}}

route();
